#!/usr/bin/env python3
"""Generate regression results from actual temporary files in clean headless Vim."""
import json
import re
from pathlib import Path
import subprocess
import tempfile

folder = Path(__file__).parent
cases = json.loads(folder.joinpath("file_cases.json").read_text())
results = []
with tempfile.TemporaryDirectory(prefix="leet-vim-files-") as temporary:
    work = Path(temporary)
    for index, case in enumerate(cases):
        source = work / "source.txt"
        saved = work / "saved.txt"
        position = work / "position.json"
        source.write_bytes(case["source"].encode())
        keys = json.dumps(case["commands"], ensure_ascii=False).replace("\\u001b", "\\<Esc>").replace("\\u0016", "\\<C-v>")
        script = work / "run.vim"
        script.write_text("set encoding=utf-8 tabstop=4 shiftwidth=4 expandtab noautoindent nofixeol\n"
            + "execute 'edit ' . fnameescape('" + str(source) + "')\n"
            + "execute \"normal! gg0\"\nexecute \"normal! \" . " + keys + "\n"
            + "let result = {'line': line('.') - 1, 'column': col('.') - 1}\n"
            + "call writefile([json_encode(result)], '" + str(position) + "')\n"
            + "execute 'write! ' . fnameescape('" + str(saved) + "')\nqa!\n")
        subprocess.run(["vim", "-Nu", "NONE", "-U", "NONE", "-i", "NONE", "-n", "-N", "-es", "-S", str(script)], check=True)
        text = saved.read_bytes().decode()
        point = json.loads(position.read_text())
        offset = sum(len(row.encode()) + 1 for row in text.split("\n")[:point["line"]]) + point["column"]
        results.append({"name": f"file-{index}", **case, "text": text, "cursor": offset})
folder.joinpath("file_reference.json").write_text(json.dumps(results, ensure_ascii=False, indent=2) + "\n")
raw = lambda value: re.sub(r'\\u([0-9a-fA-F]{4})', lambda match: '\\u{' + match.group(1) + '}', json.dumps(value, ensure_ascii=False))
rust = "// Generated by file_reference.py with clean Vim reading and writing actual files.\n"
rust += "pub(super) const CASES: &[(&str, &str, &str, &str, usize)] = &[\n"
for result in results:
    rust += "    (" + ", ".join(raw(result[field]) for field in ("name", "source", "commands", "text")) + ", " + str(result["cursor"]) + "),\n"
rust += "];\n"
folder.joinpath("file_reference.rs").write_text(rust)
print(f"Generated {len(results)} file-based Vim references")
